 "content": "from collections import deque

def transform(grid):
    # Propagate the marked color through connected empty cells, respecting 8 barriers.
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    starts = [(r, c) for r in range(h) for c in range(w) if out[r][c] == 2]
    if not starts:
        return out
    q = deque(starts)
    seen = set(starts)
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and out[nr][nc] == 0:
                seen.add((nr,nc))
                q.append((nr,nc))
    for r,c in seen:
        out[r][c] = 2
    return out
