 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # Identify horizontal obstacle rows and their openings. Propagate the marker
    # through the open corridors between successive obstacle rows.
    walls = [r for r, row in enumerate(grid) if row.count(8) >= max(2, w // 3)]
    for r in walls:
        holes = [c for c, v in enumerate(grid[r]) if v == 0]
        if not holes:
            continue
        # Color the openings themselves.
        for c in holes:
            out[r][c] = 2
        # The adjacent empty band connects the openings of the obstacle row.
        lo, hi = min(holes), max(holes)
        for rr in (r-1, r+1):
            if 0 <= rr < h and all(v != 8 for v in grid[rr]):
                for c in range(lo, hi + 1):
                    if grid[rr][c] == 0:
                        out[rr][c] = 2
    # Extend the seed's vertical alignment until the first obstacle.
    seed = next(((r,c) for r in range(h) for c in range(w) if grid[r][c] == 2), None)
    if seed:
        r,c=seed
        for dr in (-1,1):
            rr=r+dr
            while 0 <= rr < h and grid[rr][c] != 8:
                out[rr][c]=2
                rr += dr
    return out
