    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seed = next(((r,c) for r in range(h) for c in range(w) if grid[r][c] == 2), None)
    if seed is None:
        return out
    # Horizontal barriers are rows containing the repeated 8 pattern.  Their
    # zero slots are the passages; the beam spreads across the corridor between
    # the outermost passage slots and continues through each passage.
    walls = [r for r in range(h) if sum(v == 8 for v in grid[r]) >= 2]
    if not walls:
        return out
    sr, sc = seed
    # Propagate down from the seed through successive barrier rows.
    relevant = [r for r in walls if r >= sr]
    if not relevant:
        return out
    first = relevant[0]
    # The beam reaches the first barrier at its column; if blocked, it spreads
    # in the approach corridor between that barrier's passages.
    for r in range(sr, first):
        out[r][sc] = 2
    for idx, wr in enumerate(relevant):
        holes = [c for c,v in enumerate(grid[wr]) if v == 0]
        if not holes:
            continue
        lo, hi = min(holes), max(holes)
        # Fill the barrier's passage cells.
        for c in holes:
            out[wr][c] = 2
        next_wall = relevant[idx+1] if idx+1 < len(relevant) else h
        # The corridor after this barrier is illuminated up to the next barrier,
        # spanning the openings in that next barrier.
        if idx+1 < len(relevant):
            nh = [c for c,v in enumerate(grid[next_wall]) if v == 0]
            if nh:
                lo2, hi2 = min(nh), max(nh)
                for r in range(wr+1, next_wall):
                    for c in range(lo2, hi2+1):
                        if grid[r][c] == 0:
                            out[r][c] = 2
                for c in nh:
                    out[next_wall][c] = 2
        else:
            for r in range(wr+1, h):
                for c in holes:
                    if grid[r][c] == 0:
                        out[r][c] = 2
    # Before the first barrier, spread across the passages of that barrier.
    if holes:
        lo, hi = min(holes), max(holes)
        for r in range(max(0, first-1), first):
            for c in range(lo, hi+1):
                if grid[r][c] == 0:
                    out[r][c] = 2
    return out
