{
 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not seeds:
        return out
    sr, sc = seeds[0]
    # Horizontal patterned rows are gates. Their zero cells transmit the
    # descending beam; the row just above each gate is colored across the
    # span of its openings (a single opening fans across the whole row).
    gates = [r for r in range(sr + 1, h) if sum(v == 8 for v in grid[r]) >= 2]
    channels = [sc]
    previous = sr
    for gate in gates:
        openings = [c for c, v in enumerate(grid[gate]) if v == 0]
        if not openings:
            continue
        # Existing channels continue down through the open rows.
        for c in channels:
            for r in range(previous + 1, gate):
                if grid[r][c] == 0:
                    out[r][c] = 2
        # Fan horizontally immediately above this gate.
        if len(openings) == 1:
            left, right = 0, w - 1
        else:
            left, right = min(openings), max(openings)
        for c in range(left, right + 1):
            if grid[gate - 1][c] == 0:
                out[gate - 1][c] = 2
        for c in openings:
            out[gate][c] = 2
        channels = openings
        previous = gate
    # The last gate's openings carry straight to the bottom.
    for c in channels:
        for r in range(previous + 1, h):
            if grid[r][c] == 0:
                out[r][c] = 2
    return out
